value.string:
{\n
  "type": "object",\n
  "additionalProperties": true,\n
  "description": "Result of exporting an installed Business Template to the repository.",\n
  "properties": {\n
    "success": {\n
      "type": "boolean"\n
    },\n
    "operation": {\n
      "type": "string"\n
    },\n
    "business_template": {\n
      "type": "string"\n
    },\n
    "dry_run": {\n
      "type": "boolean"\n
    },\n
    "zodb_to_repository": {\n
      "type": "object"\n
    },\n
    "would_change": {\n
      "type": "object"\n
    },\n
    "conflicts": {\n
      "type": "array",\n
      "items": {\n
        "type": "string"\n
      }\n
    },\n
    "export_to_repository_safe": {\n
      "type": "boolean"\n
    },\n
    "revision": {\n
      "type": "string"\n
    },\n
    "error": {\n
      "type": "string"\n
    }\n
  }\n
}

{
 "type": "object",
 "additionalProperties": false,
 "required": [
 "business_template"
 ],
 "properties": {
 "business_template": {
 "type": "string",
 "description": "Bare directory name of the Business Template to export."
 },
 "dry_run": {
 "type": [
 "boolean",
 "integer"
 ],
 "default": false,
 "description": "Preview what would be written/committed without touching the repository."
 },
 "force": {
 "type": [
 "boolean",
 "integer"
 ],
 "default": false,
 "description": "Overwrite conflicting local edits / drop untracked files."
 },
 "changelog": {
 "type": "string",
 "default": "",
 "description": "Git commit message for the export."
 }
 }
 }
